import espeakMap from "./espeak-map.json";

/**
 * Speaks an IPA transcription with eSpeak NG (compiled to WebAssembly).
 *
 * eSpeak does not read IPA. It reads its own phoneme codes, and each language
 * voice has its own set. lib/espeak-map.json lists, for each IPA sound, the
 * code in each voice that eSpeak itself reports as that sound (generated by
 * scripts/espeak-map/, which asks eSpeak to print the IPA for every code).
 */

type EspeakModule = {
  FS: { readFile(path: string): Uint8Array; unlink(path: string): void };
};
type EspeakFactory = (options: {
  arguments: string[];
  wasmBinary?: ArrayBuffer;
  print?: (s: string) => void;
  printErr?: (s: string) => void;
}) => Promise<EspeakModule>;

// IPA sound -> { voice -> eSpeak phoneme code }
const MAP = espeakMap.map as Record<string, Record<string, string>>;
// Voices to prefer when several cover a word equally well.
const VOICE_ORDER: string[] = espeakMap.voiceOrder;

const TIE = /[͜͡]/g;
const SOUNDS = Object.keys(MAP).sort((a, b) => b.length - a.length);

// Marks handled the same way in every voice (eSpeak phoneme input syntax).
const MARKS: Record<string, string> = { "ˈ": "'", "ˌ": ",", " ": " ", ".": "" };

type Segment = { ipa: string; voices: Record<string, string> | null };

/** Splits IPA text into the longest sounds eSpeak knows, plus stress marks and spaces. */
function segment(ipa: string): Segment[] {
  const text = ipa.normalize("NFC").replace(TIE, "");
  const out: Segment[] = [];
  let i = 0;
  while (i < text.length) {
    const sound = SOUNDS.find((s) => text.startsWith(s, i));
    if (sound) {
      out.push({ ipa: sound, voices: MAP[sound] });
      i += sound.length;
      continue;
    }
    const ch = String.fromCodePoint(text.codePointAt(i)!);
    out.push({ ipa: ch, voices: null });
    i += ch.length;
  }
  return out;
}

type Run = { voice: string; phonemes: string };

/** Groups the sounds into as few runs as possible, each spoken by one voice. */
function plan(segments: Segment[]): { runs: Run[]; unknown: string[] } {
  const runs: Run[] = [];
  const unknown: string[] = [];
  let i = 0;
  while (i < segments.length) {
    // Pick the voice that can say the longest stretch from here.
    let best = { voice: "", end: i };
    for (const voice of VOICE_ORDER) {
      let end = i;
      while (end < segments.length) {
        const s = segments[end];
        if (s.voices ? !(voice in s.voices) : !(s.ipa in MARKS)) break;
        end++;
      }
      if (end > best.end) best = { voice, end };
    }
    if (best.end === i) {
      // No voice has this sound (or it is a mark that can't start a run).
      const s = segments[i];
      if (!(s.ipa in MARKS)) unknown.push(s.ipa);
      i++;
      continue;
    }
    const part = segments.slice(i, best.end);
    i = best.end;
    if (!part.some((s) => s.voices)) continue; // only stress marks or spaces
    const codes = part.map((s) => (s.voices ? s.voices[best.voice] : MARKS[s.ipa])).filter(Boolean);
    // "|" stops eSpeak reading two adjacent codes as one longer code (e.g. t + S as tS).
    runs.push({ voice: best.voice, phonemes: codes.join("|").replace(/\|?( |'|,)\|?/g, "$1") });
  }
  return { runs, unknown };
}

// Where public/espeak/ is served from (a sub-path on GitHub Pages).
const ESPEAK_URL = `${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/espeak`;

let factory: Promise<{ create: EspeakFactory; wasm: ArrayBuffer }> | null = null;

function loadEspeak() {
  factory ??= (async () => {
    const missing = new Error(
      "The speech engine files are missing from public/espeak/. Stop the dev server, run `npm install`, then `npm run dev` again.",
    );
    const [mod, wasm] = await Promise.all([
      (import(/* webpackIgnore: true */ `${ESPEAK_URL}/espeak-ng.js`) as Promise<{ default: EspeakFactory }>).catch(
        () => {
          throw missing;
        },
      ),
      fetch(`${ESPEAK_URL}/espeak-ng.wasm`).then((r) => {
        if (!r.ok) throw missing;
        return r.arrayBuffer();
      }),
    ]);
    return { create: mod.default, wasm };
  })();
  factory.catch(() => (factory = null));
  return factory;
}

async function synthesize(run: Run): Promise<ArrayBuffer> {
  const { create, wasm } = await loadEspeak();
  const errors: string[] = [];
  const espeak = await create({
    arguments: ["-v", run.voice, "-w", "/out.wav", `[[${run.phonemes}]]`],
    wasmBinary: wasm.slice(0),
    print: () => {},
    printErr: (s) => errors.push(s),
  });
  const wav = espeak.FS.readFile("/out.wav");
  if (!wav.length) throw new Error(errors.join(" ") || "The speech engine produced no audio.");
  return wav.slice().buffer;
}

let audioContext: AudioContext | null = null;

/**
 * Plays the IPA text. Resolves with the symbols that could not be pronounced
 * (they are skipped), once playback has finished.
 */
export async function speakIpa(ipa: string): Promise<string[]> {
  const { runs, unknown } = plan(segment(ipa));
  if (!runs.length) return unknown;

  audioContext ??= new AudioContext();
  const ctx = audioContext;
  if (ctx.state === "suspended") await ctx.resume();

  const buffers = await Promise.all(runs.map(async (r) => ctx.decodeAudioData(await synthesize(r))));
  let at = ctx.currentTime + 0.05;
  for (const buffer of buffers) {
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.start(at);
    at += buffer.duration;
  }
  await new Promise((resolve) => setTimeout(resolve, (at - ctx.currentTime) * 1000));
  return unknown;
}
